ETAPA1 = range(1, 17)


def verificar():
    errores = []
    assert len(CLASES) == 36
    for i, c in enumerate(CLASES, 1):
        if c["n"] != i:
            errores.append(f"numeración {c['n']} != {i}")
        ti, td, tc = c["t"]
        if ti + td + tc != 80:
            errores.append(f"clase {i}: total {ti+td+tc}")
        s = sum(m for _, m, _ in c["dev"])
        if s != td:
            errores.append(f"clase {i}: subdivisiones del Desarrollo {s} != {td}")
        if not 3 <= len(c["ind"]) <= 4:
            errores.append(f"clase {i}: {len(c['ind'])} indicadores")
        if isinstance(c["ev"], dict) and set(c["ev"]) != set(c["caps"]):
            errores.append(f"clase {i}: evidencias {sorted(c['ev'])} != capacidades {sorted(c['caps'])}")
        if len(c["caps"]) > 1 and not isinstance(c["ev"], dict):
            errores.append(f"clase {i}: varias capacidades sin evidencia por capacidad")
    return errores


if __name__ == "__main__":
    e = verificar()
    print("\n".join(e) if e else "contenido OK")
